#!/usr/bin/env python3
"""config_parser.py — AsyncRAT config extraction from de4dot output.

Plans §5-6: extracts config fields from de4dot-deobfuscated .NET assemblies.
Target fields: Hosts, Ports, AESKey, Mutex, InstallDir, Certificate, Pastebin, Telegram.

Usage:
    python3 config_parser.py <path_to_de4dot_output_dir> [--output <json_file>]
"""

import argparse
import json
import re
import sys
from pathlib import Path


def find_config_json(res_dir: Path) -> Path | None:
    """Find the config.json generated by de4dot in the resource directory."""
    # de4dot typically extracts config to a known structure
    candidates = list(res_dir.rglob("config.json"))
    if not candidates:
        return None
    # Return the first match (de4dot usually produces one)
    return candidates[0]


def parse_config_file(config_path: Path) -> dict:
    """Parse the de4dot-extracted config.json file.

    de4dot outputs a JSON or serialized config that may contain:
    - String values directly
    - Obfuscated/encoded values that need decoding
    """
    try:
        text = config_path.read_text(encoding="utf-8", errors="replace")
    except Exception as e:
        print(f"WARNING: could not read {config_path}: {e}", file=sys.stderr)
        return {}

    # Try to find JSON in the file
    # de4dot may wrap things; extract the first {...} block
    match = re.search(r"\{\s*.*?\s*\}", text, re.DOTALL)
    if not match:
        return {}

    raw = match.group(0)
    try:
        data = json.loads(raw)
        if isinstance(data, dict):
            return data
    except json.JSONDecodeError:
        pass

    # If not valid JSON, try to extract key-value pairs
    # de4dot configs sometimes have "key": "value" format
    result = {}
    # Match "key": "value" patterns (handling escaped quotes)
    pairs = re.findall(r'"(\w+)"\s*:\s*"((?:[^"\\]|\\.)*)"', raw)
    for key, value in pairs:
        result[key] = value

    return result


def decode_base64_safe(text: str) -> str | None:
    """Attempt base64 decode, return decoded string or None."""
    import base64
    try:
        decoded = base64.b64decode(text).decode("utf-8", errors="replace")
        return decoded
    except Exception:
        return None


def extract_config_from_assembly(pe_path: Path) -> dict:
    """Attempt to extract AsyncRAT config from a .NET assembly.

    Tries multiple approaches:
    1. de4dot output config.json if present
    2. Raw resource search for known config patterns
    3. String pattern matching in the binary
    """
    config = {}

    # Try de4dot-extracted resources first
    # de4dot typically puts things in a "Cleaned" or de4dot output directory
    # Look for config.json patterns

    # If the path itself is a directory, search for config
    if pe_path.is_dir():
        config_json = find_config_json(pe_path)
        if config_json:
            config.update(parse_config_file(config_json))

    # If it's a file, try to extract resources
    if pe_path.is_file():
        # Try to find config-like strings in the binary
        try:
            data = pe_path.read_bytes()
            # Common AsyncRAT patterns - these are heuristic
            patterns = {
                "aes_key": rb"[Aa][Ee][Ss][-_]? key[:\s]+([A-Za-z0-9+/=]{16,32})",
                "mutex": rb"[Mm][Uu][Tt][Ee][xX][:\s]+([A-Za-z0-9_.\-]{3,64})",
                "pastebin": rb"[Pp]aste[_-]?[Bb]in[:\s]+(https?://[^\s]{10,})",
                "telegram": rb"[Tt]elegram[_-]?[Aa]pi[_-]?[Idd][:\s]*([0-9]{4,9})",
            }

            for field, pattern in patterns.items():
                m = re.search(pattern, data.decode("utf-8", errors="replace"), re.IGNORECASE)
                if m:
                    config[field] = m.group(1).strip()
        except Exception:
            pass

    return config


def main():
    ap = argparse.ArgumentParser(description="AsyncRAT config extraction from de4dot output")
    ap.add_argument("sample", help="Path to .NET assembly or de4dot output directory")
    ap.add_argument("--output", "-o", help="Output JSON file path")
    args = ap.parse_args()

    src = Path(args.sample)
    if not src.exists():
        print(f"ERROR: not found: {src}", file=sys.stderr)
        sys.exit(1)

    config = extract_config_from_assembly(src)

    # Print results
    if config:
        print(f"Extracted {len(config)} config field(s) from {src}:")
        for key, value in config.items():
            print(f"  {key}: {value}")
    else:
        print(f"No config fields found in {src}")
        print("  - Try running de4dot first: https://github.com/de4dot/de4dot")
        print("  - Or manually inspect resources with extract_resources.py")

    # Write output if requested
    if args.output and config:
        out_path = Path(args.output)
        out_path.write_text(json.dumps(config, indent=2) + "\n", encoding="utf-8")
        print(f"\nConfig written to: {out_path}")


if __name__ == "__main__":
    main()